  if (isLovableOrVite) {
    // SAFE MODE: Copy a standalone helper file instead of adding file: dependency.
    // file: deps break in Lovable, Vercel, and all CI/CD environments.
    const helperContent = `/**
 * Claude Hub Agent Helper — auto-generated by Claude Hub install-sdk
 * Calls Claude Hub agents via HTTP. No npm dependency required.
 * Claude Hub must be running at localhost:3847 (auto-starts on login).
 *
 * Usage (browser/Vite):
 *   import { callAgent, isOnline } from '@/lib/claudeHub'
 *   const result = await callAgent('quill', 'Write a tagline')
 *
 * NOTE: Only works during local development. Claude Hub is not available
 * in production/deployed environments (Lovable, Vercel, etc.).
 */

const CLAUDE_HUB_URL = import.meta.env.VITE_CLAUDE_HUB_URL || 'http://localhost:3847'

export async function callAgent(agentName, prompt, timeoutMs = 120000) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(\`\${CLAUDE_HUB_URL}/api/playground/run\`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentName, prompt }),
      signal: controller.signal,
    })
    clearTimeout(timeout)
    if (!response.ok) throw new Error(\`Claude Hub returned \${response.status}\`)

    const text = await response.text()
    const events = text
      .split('\\n')
      .filter(line => line.startsWith('data: '))
      .map(line => { try { return JSON.parse(line.slice(6)) } catch { return null } })
      .filter(Boolean)

    const errorEvent = events.find(e => e.type === 'error')
    if (errorEvent) return { success: false, output: '', agent: agentName, error: errorEvent.error }

    const doneEvent = events.find(e => e.type === 'done' || e.type === 'complete')
    return { success: true, output: doneEvent?.output || '', agent: agentName }
  } catch (err) {
    clearTimeout(timeout)
    const msg = err instanceof Error ? err.message : String(err)
    return {
      success: false,
      output: '',
      agent: agentName,
      error: msg.includes('abort')
        ? \`Timed out after \${timeoutMs / 1000}s\`
        : \`Claude Hub not reachable — is it running?\`,
    }
  }
}

export async function listAgents() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`)
    if (!res.ok) throw new Error(\`HTTP \${res.status}\`)
    return await res.json()
  } catch { return [] }
}

export async function isOnline() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`, { signal: AbortSignal.timeout(3000) })
    return res.ok
  } catch { return false }
}
`;

    // Write helper to src/lib/claudeHub.ts
    const libDir = path.join(resolvedProject, 'src', 'lib');
    if (!fs.existsSync(libDir)) {
      fs.mkdirSync(libDir, { recursive: true });
    }

    const helperPath = path.join(libDir, 'claudeHub.ts');
    fs.writeFileSync(helperPath, helperContent);

    // Add env var hint to .env.local if it exists (or create it)
    const envLocalPath = path.join(resolvedProject, '.env.local');
    let envContent = '';
    if (fs.existsSync(envLocalPath)) {
      envContent = fs.readFileSync(envLocalPath, 'utf-8');
    }
    if (!envContent.includes('VITE_CLAUDE_HUB_URL')) {
      envContent += `\n# Claude Hub — local agent server (only works in dev)\nVITE_CLAUDE_HUB_URL=http://localhost:3847\n`;
      fs.writeFileSync(envLocalPath, envContent);
    }

    res.json({
      success: true,
      method: 'helper-file',
      helperPath: 'src/lib/claudeHub.ts',
      usage: "import { callAgent } from '@/lib/claudeHub'",
      note: 'Lovable/Vite project detected. Installed standalone helper file instead of file: dependency. No npm package needed — works via direct HTTP calls to Claude Hub.',
    });

  } else {
    // NON-VITE PROJECT (e.g., Node.js server): file: dep within same project is OK,
    // but cross-project file: deps still break CI. Use copy if outside project.
    const pkgPath = path.join(resolvedProject, 'package.json');
    let pkg = { name: path.basename(resolvedProject), version: '1.0.0', dependencies: {} };
    if (fs.existsSync(pkgPath)) {
      try {
        pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
      } catch {
        return res.status(500).json({ error: 'Could not parse project package.json' });
      }
    }

    // Check if SDK is inside this project (safe) or outside (unsafe for CI)
    const relPath = path.relative(resolvedProject, sdkAbsPath);
    const isInsideProject = !relPath.startsWith('..');

    if (!pkg.dependencies) pkg.dependencies = {};

    if (isInsideProject) {
      // SDK is within the project — file: dep is safe for local-only servers
      pkg.dependencies['@boldteq/agents'] = `file:${relPath}`;
    } else {
      // SDK is outside the project — copy it in to avoid cross-project file: dep
      const targetSdkDir = path.join(resolvedProject, 'lib', 'boldteq-agents');
      fs.mkdirSync(targetSdkDir, { recursive: true });
      const sdkFiles = ['index.js', 'package.json'];
      for (const f of sdkFiles) {
        const src = path.join(sdkAbsPath, f);
        if (fs.existsSync(src)) {
          fs.copyFileSync(src, path.join(targetSdkDir, f));
        }
      }
      pkg.dependencies['@boldteq/agents'] = 'file:lib/boldteq-agents';
    }

    fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

    // Run npm install
    try {
      execSync('npm install', { cwd: resolvedProject, timeout: 60000, stdio: 'pipe' });
      res.json({
        success: true,
        method: isInsideProject ? 'file-dep-internal' : 'copy-sdk',
        note: isInsideProject
          ? 'SDK is inside the project — added file: dependency (safe for local servers).'
          : 'SDK was outside the project — copied to lib/boldteq-agents to avoid cross-project file: dep.',
      });
    } catch (err) {
      res.status(500).json({ error: err.message || 'npm install failed' });
    }
  }
});

app.post('/api/setup/install-screenshot', (req, res) => {
  const { projectPath } = req.body;
  if (!projectPath || typeof projectPath !== 'string') {
    return res.status(400).json({ error: 'projectPath is required' });
  }

  const resolvedProject = path.resolve(projectPath);
  if (!fs.existsSync(resolvedProject) || !fs.statSync(resolvedProject).isDirectory()) {
    return res.status(400).json({ error: 'Project path does not exist' });
  }

  const config = loadConfig();
  const allowedRoots = (config.projectDirs || []).map(d => path.resolve(d.replace(/^~/, HOME)));
  const isAllowed = allowedRoots.some(root => resolvedProject.startsWith(root));
  if (!isAllowed) {
    return res.status(403).json({ error: 'Path outside allowed project directories' });
  }

  try {
    // 1. Copy the canonical screenshot.mjs from Rankora (or write it inline)
    const scriptsDir = path.join(resolvedProject, 'scripts');
    ensureDir(scriptsDir);
    const destScript = path.join(scriptsDir, 'screenshot.mjs');

    // Use Rankora's script as the canonical source if it exists, otherwise write inline
    const rankora = path.join(HOME, 'Desktop', 'Boldteq App', 'Rankora', 'scripts', 'screenshot.mjs');
    if (fs.existsSync(rankora)) {
      fs.copyFileSync(rankora, destScript);
    } else {
      // Inline canonical script
      const scriptContent = `#!/usr/bin/env node
/**
 * Auto-Screenshot Utility — installed by Claude Hub
 * Usage:
 *   node scripts/screenshot.mjs                  # Desktop, all routes
 *   node scripts/screenshot.mjs --viewport all   # Mobile + tablet + desktop
 *   node scripts/screenshot.mjs --dark           # Dark mode
 *   node scripts/screenshot.mjs --full-page      # Full scroll capture
 *   node scripts/screenshot.mjs --routes /,/dashboard
 */
import { chromium } from 'playwright';
import { mkdirSync, existsSync, readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, resolve } from 'path';

const SCREENSHOT_DIR = resolve('.screenshots');
const VIEWPORTS = {
  mobile:  { width: 375, height: 812 },
  tablet:  { width: 768, height: 1024 },
  desktop: { width: 1440, height: 900 },
};

function detectPort() {
  const files = [
    { path: 'vite.config.ts', regex: /port:\\s*(\\d+)/ },
    { path: 'vite.config.js', regex: /port:\\s*(\\d+)/ },
    { path: 'next.config.js', regex: /port:\\s*(\\d+)/ },
    { path: 'next.config.mjs', regex: /port:\\s*(\\d+)/ },
  ];
  for (const f of files) {
    if (existsSync(f.path)) {
      const m = readFileSync(f.path, 'utf-8').match(f.regex);
      if (m) return parseInt(m[1]);
    }
  }
  if (existsSync('vite.config.ts') || existsSync('vite.config.js')) return 8080;
  return 3000;
}

function detectRoutes() {
  const routes = new Set(['/']);
  const routeFiles = ['src/App.tsx', 'src/app/App.tsx'];
  for (const file of routeFiles) {
    if (!existsSync(file)) continue;
    const content = readFileSync(file, 'utf-8');
    for (const m of content.matchAll(/path=["']([^"']+)["']/g)) {
      const r = m[1];
      if (!r.includes(':') && !r.includes('*') && !r.includes('$')) {
        routes.add(r.startsWith('/') ? r : '/' + r);
      }
    }
  }
  if (existsSync('src/pages')) {
    try {
      for (const f of readdirSync('src/pages').filter(f => f.endsWith('.tsx') && f !== 'NotFound.tsx')) {
        const name = f.replace('.tsx', '');
        routes.add(name === 'Index' ? '/' : '/' + name.charAt(0).toLowerCase() + name.slice(1));
      }
    } catch {}
  }
  return [...routes].sort();
}

function parseArgs() {
  const args = process.argv.slice(2);
  const p = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--port') p.port = parseInt(args[++i]);
    if (args[i] === '--routes') p.routes = args[++i].split(',');
    if (args[i] === '--viewport') p.viewport = args[++i];
    if (args[i] === '--dark') p.dark = true;
    if (args[i] === '--full-page') p.fullPage = true;
  }
  return p;
}

async function run() {
  const args = parseArgs();
  const port = args.port || detectPort();
  const baseUrl = \`http://localhost:\${port}\`;
  const routes = args.routes || detectRoutes();
  const viewportKeys = args.viewport === 'all' ? Object.keys(VIEWPORTS) : [args.viewport || 'desktop'];

  try {
    await fetch(baseUrl, { signal: AbortSignal.timeout(3000) });
  } catch {
    console.error(\`Dev server not running at \${baseUrl}. Start it: npm run dev\`);
    process.exit(1);
  }

  mkdirSync(SCREENSHOT_DIR, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const results = [];

  for (const vpKey of viewportKeys) {
    const context = await browser.newContext({
      viewport: VIEWPORTS[vpKey],
      deviceScaleFactor: 2,
      colorScheme: args.dark ? 'dark' : 'light',
    });
    const page = await context.newPage();
    const consoleErrors = [];
    page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });

    for (const route of routes) {
      const filename = \`\${vpKey}_\${route.replace(/\\//g, '_').replace(/^_/, '') || 'home'}\${args.dark ? '_dark' : ''}.png\`;
      try {
        const response = await page.goto(\`\${baseUrl}\${route}\`, { waitUntil: 'networkidle', timeout: 15000 });
        await page.waitForTimeout(2000);
        await page.screenshot({ path: join(SCREENSHOT_DIR, filename), fullPage: args.fullPage || false });
        results.push({ route, viewport: vpKey, file: filename, status: response?.status(), consoleErrors: [...consoleErrors] });
        console.log(\`  OK  \${vpKey.padEnd(7)} \${route.padEnd(20)} -> \${filename}\`);
        consoleErrors.length = 0;
      } catch (err) {
        results.push({ route, viewport: vpKey, file: null, status: 'FAILED', error: err.message });
        console.log(\`  ERR \${vpKey.padEnd(7)} \${route.padEnd(20)} -> \${err.message}\`);
      }
    }
    await context.close();
  }

  await browser.close();
  const summary = { total: results.length, success: results.filter(r => r.file).length, failed: results.filter(r => !r.file).length };
  writeFileSync(join(SCREENSHOT_DIR, 'manifest.json'), JSON.stringify({ timestamp: new Date().toISOString(), baseUrl, routes, viewports: viewportKeys, screenshots: results, summary }, null, 2));
  console.log(\`\\n  \${summary.success} captured, \${summary.failed} failed\\n\`);
}

run().catch(err => { console.error(err.message); process.exit(1); });
`;
      fs.writeFileSync(destScript, scriptContent, 'utf-8');
    }

    // 2. Add playwright to devDependencies (only if not already present)
    const pkgPath = path.join(resolvedProject, 'package.json');
    let addedPlaywright = false;
    if (fs.existsSync(pkgPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
        const hasPw = (pkg.dependencies?.playwright) || (pkg.devDependencies?.playwright)
          || (pkg.dependencies?.['@playwright/test']) || (pkg.devDependencies?.['@playwright/test']);
        if (!hasPw) {
          if (!pkg.devDependencies) pkg.devDependencies = {};
          pkg.devDependencies['playwright'] = '^1.52.0';
          fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf-8');
          addedPlaywright = true;
        }
      } catch {}
    }

    // 3. Add .screenshots/ to .gitignore
    const gitignorePath = path.join(resolvedProject, '.gitignore');
    let gitignore = fs.existsSync(gitignorePath) ? fs.readFileSync(gitignorePath, 'utf-8') : '';
    if (!gitignore.includes('.screenshots')) {
      gitignore += '\n# Screenshot tool\n.screenshots/\n';
      fs.writeFileSync(gitignorePath, gitignore, 'utf-8');
    }

    res.json({
      ok: true,
      scriptPath: 'scripts/screenshot.mjs',
      addedPlaywright,
      nextSteps: addedPlaywright
        ? ['npm install', 'npx playwright install chromium', 'node scripts/screenshot.mjs']
        : ['npx playwright install chromium', 'node scripts/screenshot.mjs'],
    });
  } catch (err) {
    res.status(500).json({ error: err.message || 'Install failed' });
  }
});

