    res.json({
      totalEntries: entries.length,
      actionCounts,
      dailyCounts,
      hotFiles,
      totalAdded,
      totalRemoved,
      firstEntry: entries.length ? entries[0].timestamp : null,
      lastEntry: entries.length ? entries[entries.length - 1].timestamp : null,
    });
