    const helperContent = `/**
 * Claude Hub Agent Helper — auto-generated by Claude Hub install-sdk
 * Calls Claude Hub agents via HTTP. No npm dependency required.
 * Claude Hub must be running at localhost:3847 (auto-starts on login).
 *
 * Usage (browser/Vite):
 *   import { callAgent, isOnline } from '@/lib/claudeHub'
 *   const result = await callAgent('quill', 'Write a tagline')
 *
 * NOTE: Only works during local development. Claude Hub is not available
 * in production/deployed environments (Lovable, Vercel, etc.).
 */

const CLAUDE_HUB_URL = import.meta.env.VITE_CLAUDE_HUB_URL || 'http://localhost:3847'

export async function callAgent(agentName, prompt, timeoutMs = 120000) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(\`\${CLAUDE_HUB_URL}/api/playground/run\`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentName, prompt }),
      signal: controller.signal,
    })
    clearTimeout(timeout)
    if (!response.ok) throw new Error(\`Claude Hub returned \${response.status}\`)

    const text = await response.text()
    const events = text
      .split('\\n')
      .filter(line => line.startsWith('data: '))
      .map(line => { try { return JSON.parse(line.slice(6)) } catch { return null } })
      .filter(Boolean)

    const errorEvent = events.find(e => e.type === 'error')
    if (errorEvent) return { success: false, output: '', agent: agentName, error: errorEvent.error }

    const doneEvent = events.find(e => e.type === 'done' || e.type === 'complete')
    return { success: true, output: doneEvent?.output || '', agent: agentName }
  } catch (err) {
    clearTimeout(timeout)
    const msg = err instanceof Error ? err.message : String(err)
    return {
      success: false,
      output: '',
      agent: agentName,
      error: msg.includes('abort')
        ? \`Timed out after \${timeoutMs / 1000}s\`
        : \`Claude Hub not reachable — is it running?\`,
    }
  }
}

export async function listAgents() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`)
    if (!res.ok) throw new Error(\`HTTP \${res.status}\`)
    return await res.json()
  } catch { return [] }
}

export async function isOnline() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`, { signal: AbortSignal.timeout(3000) })
    return res.ok
  } catch { return false }
}
`;

    // Write helper to src/lib/claudeHub.ts
    const libDir = path.join(resolvedProject, 'src', 'lib');
    if (!fs.existsSync(libDir)) {
      fs.mkdirSync(libDir, { recursive: true });
    }

    const helperPath = path.join(libDir, 'claudeHub.ts');
    fs.writeFileSync(helperPath, helperContent);

    // Add env var hint to .env.local if it exists (or create it)
    const envLocalPath = path.join(resolvedProject, '.env.local');
    let envContent = '';
    if (fs.existsSync(envLocalPath)) {
      envContent = fs.readFileSync(envLocalPath, 'utf-8');
    }
    if (!envContent.includes('VITE_CLAUDE_HUB_URL')) {
      envContent += `\n# Claude Hub — local agent server (only works in dev)\nVITE_CLAUDE_HUB_URL=http://localhost:3847\n`;
      fs.writeFileSync(envLocalPath, envContent);
    }

    res.json({
      success: true,
      method: 'helper-file',
      helperPath: 'src/lib/claudeHub.ts',
      usage: "import { callAgent } from '@/lib/claudeHub'",
      note: 'Lovable/Vite project detected. Installed standalone helper file instead of file: dependency. No npm package needed — works via direct HTTP calls to Claude Hub.',
    });

  } else {
    // NON-VITE PROJECT (e.g., Node.js server): file: dep within same project is OK,
    // but cross-project file: deps still break CI. Use copy if outside project.
    const pkgPath = path.join(resolvedProject, 'package.json');
    let pkg = { name: path.basename(resolvedProject), version: '1.0.0', dependencies: {} };
    if (fs.existsSync(pkgPath)) {
      try {
        pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
      } catch {
        return res.status(500).json({ error: 'Could not parse project package.json' });
      }
    }

    // Check if SDK is inside this project (safe) or outside (unsafe for CI)
    const relPath = path.relative(resolvedProject, sdkAbsPath);
    const isInsideProject = !relPath.startsWith('..');

    if (!pkg.dependencies) pkg.dependencies = {};

    if (isInsideProject) {
      // SDK is within the project — file: dep is safe for local-only servers
      pkg.dependencies['@boldteq/agents'] = `file:${relPath}`;
    } else {
      // SDK is outside the project — copy it in to avoid cross-project file: dep
      const targetSdkDir = path.join(resolvedProject, 'lib', 'boldteq-agents');
      fs.mkdirSync(targetSdkDir, { recursive: true });
      const sdkFiles = ['index.js', 'package.json'];
      for (const f of sdkFiles) {
        const src = path.join(sdkAbsPath, f);
        if (fs.existsSync(src)) {
          fs.copyFileSync(src, path.join(targetSdkDir, f));
        }
      }
      pkg.dependencies['@boldteq/agents'] = 'file:lib/boldteq-agents';
    }

    fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

    // Run npm install
    try {
      execSync('npm install', { cwd: resolvedProject, timeout: 60000, stdio: 'pipe' });
      res.json({
        success: true,
        method: isInsideProject ? 'file-dep-internal' : 'copy-sdk',
        note: isInsideProject
          ? 'SDK is inside the project — added file: dependency (safe for local servers).'
          : 'SDK was outside the project — copied to lib/boldteq-agents to avoid cross-project file: dep.',
      });
    } catch (err) {
      res.status(500).json({ error: err.message || 'npm install failed' });
    }
  }
});

