              }`}
            >
              <Code className="w-3.5 h-3.5" /> Source
            </button>
          </div>

          {dirty && (
            <button onClick={handleReset} className="flex items-center gap-1.5 px-3 py-2 text-xs text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors">
